namespace ghidra.features.bsim.query.protocol;






using generic.lsh.vector;
using ghidra.features.bsim.query;
using ghidra.util.xml;
using ghidra.xml;

public class ResponseOptionalValues : QueryResponseRecord {

	// FIXME: XML serialization assumes String-based resultArray which is incorrect

	public object[] resultArray;		// Array of values corresponding to queried keys
	public bool tableExists;			// false if the query failed because the table doesn't exist

	public ResponseOptionalValues() : base("responseoptionalvalues")
    {
		resultArray = null;
		tableExists = true;
	}

	/* @Override */
	public void saveXml(Writer fwrite)
    {
		fwrite.append('<').append(name).append(">\n");
		if (!tableExists) {
			fwrite.append("<exists>false</exists>\n");
		}
		if (resultArray != null) {
			foreach (object value in resultArray) {
				fwrite.append("<val>");
				SpecXmlUtils.xmlEscapeWriter(fwrite, value.toString());
				fwrite.append("</val>\n");
			}
		}
		fwrite.append("</").append(name).append(">\n");
	}

	/* @Override */
	public void restoreXml(XmlPullParser parser, LSHVectorFactory vectorFactory)
    {
		tableExists = true;
		resultArray = null;
		List<object> resValues = new List<object>();
		parser.start(name);
		if (parser.peek().getName().equals("exists")) {
			parser.start("exists");
			tableExists = SpecXmlUtils.decodeBoolean(parser.end().getText());
		}
		while (parser.peek().isStart()) {
			parser.start();
			string value = parser.end().getText();
			resValues.add(value);
		}
		parser.end();
		if (!resValues.isEmpty()) {
			resultArray = new object[resValues.size()];
			resValues.toArray(resultArray);
		}
	}

}
